(()=>{'use strict';
const $=s=>document.querySelector(s), $$=s=>[...document.querySelectorAll(s)];
const els={auth:$('#auth'),bootCard:$('#bootCard'),authCard:$('#authCard'),pin:$('#pin'),authError:$('#authError'),clock:$('#clock'),stageName:$('#stageName'),lobby:$('#lobbyView'),live:$('#liveView'),results:$('#resultsView'),reviewView:$('#reviewView'),joined:$('#joinedCount'),lobbyConnected:$('#lobbyConnected'),lobbyNames:$('#lobbyNames'),lobbyNameCount:$('#lobbyNameCount'),qr:$('#qr'),qrFallback:$('#qrFallback'),joinUrl:$('#joinUrl'),linkSelect:$('#linkSelect'),liveRanks:$('#liveRanks'),finalRanks:$('#finalRanks'),podium:$('#podium'),status:$('#liveStatus'),completeCount:$('#completeCount'),completeBar:$('#completeBar'),liveJoined:$('#liveJoined'),liveConnected:$('#liveConnected'),footerInfo:$('#footerInfo'),feedback:$('#feedback'),start:$('#start'),pause:$('#pause'),end:$('#end'),reset:$('#reset'),review:$('#review'),exportData:$('#exportData'),winners:$('#winners'),fullscreen:$('#fullscreen'),reviewNum:$('#reviewNum'),reviewTheme:$('#reviewTheme'),reviewQuestion:$('#reviewQuestion'),reviewOptions:$('#reviewOptions'),reviewExplain:$('#reviewExplain'),reviewAnswered:$('#reviewAnswered'),reviewCorrect:$('#reviewCorrect'),reviewUnanswered:$('#reviewUnanswered'),prev:$('#prevQuestion'),next:$('#nextQuestion'),back:$('#backWinners'),finalSummary:$('#finalSummary')};
let state=null,skew=0,pin='',view='',reviewData=null,reviewIndex=0,joinedUrl='',events=null,cloudPollBusy=false;
const fmt=ms=>{let s=Math.max(0,Math.ceil(ms/1000));return String(Math.floor(s/60)).padStart(2,'0')+':'+String(s%60).padStart(2,'0');};
function message(s){els.feedback.textContent=s;}
async function hostFetch(route,opt={}){const r=await fetch('/api/host/'+route,{...opt,headers:{...opt.headers,'x-host-pin':pin},cache:'no-store'});const d=await r.json();if(!r.ok)throw Error(d.error||'Permintaan gagal');return d;}
function safeView(which){const views={lobby:els.lobby,live:els.live,results:els.results,review:els.reviewView};for(const [key,elem] of Object.entries(views))elem.classList.toggle('hidden',which!==key);view=which;const url='/presenter/'+which;if(location.pathname!==url)history.replaceState(null,'',url);els.stageName.textContent=({lobby:'LOBBY',live:'LIVE',results:'RESULTS',review:'REVIEW'})[which]||which.toUpperCase();const status=state?.status;
 els.start.classList.toggle('hidden',which!=='lobby');els.pause.classList.toggle('hidden',which!=='live');els.end.classList.toggle('hidden',which!=='live');els.review.classList.toggle('hidden',which!=='results');els.exportData.classList.toggle('hidden',which!=='results');els.winners.classList.toggle('hidden',which!=='review');els.reset.classList.toggle('hidden',!['results','lobby'].includes(which));els.start.disabled=!state||status!=='waiting'||state.players===0;els.pause.textContent=status==='paused'?'Resume':'Pause';els.footerInfo.textContent=which==='lobby'?'Scan QR to join · Waiting for players':which==='live'?'Live scores · Every point counts!':which==='results'?'Well played, everyone!':'Let’s review the answers together';}
function drawRank(items,container,limit){const key=JSON.stringify(items.slice(0,limit).map(p=>[p.rank,p.name,p.score]));if(container.dataset.rankKey===key)return;container.dataset.rankKey=key;container.replaceChildren();if(!items.length){const d=document.createElement('div');d.className='rank-row';d.textContent='Leaderboard starts here — scores are on the way!';container.append(d);return;}for(const p of items.slice(0,limit)){const row=document.createElement('div');row.className='rank-row';const pos=document.createElement('span');pos.className='rank-position';pos.textContent='#'+p.rank;const who=document.createElement('span');who.className='rank-person';who.textContent=p.name;const score=document.createElement('span');score.className='rank-score';score.textContent=p.score.toLocaleString('ms-MY');row.append(pos,who,score);container.append(row);}}
function drawLobby(names){
 const list=Array.isArray(names)?names:[];
 const key=JSON.stringify(list.map(p=>[p.name,p.connected]));
 els.lobbyNameCount.textContent=list.length;
 if(els.lobbyNames.dataset.namesKey===key)return;
 els.lobbyNames.dataset.namesKey=key;
 els.lobbyNames.replaceChildren();
 if(!list.length){const empty=document.createElement('div');empty.className='lobby-empty';empty.textContent='Nickname peserta akan muncul di sini…';els.lobbyNames.append(empty);return;}
 for(const player of list){const chip=document.createElement('span');chip.className='player-chip'+(player.connected?' is-online':' is-away');chip.textContent='✿ '+player.name;chip.title=player.connected?'Online':'Offline';els.lobbyNames.append(chip);}
}
function podium(items){els.podium.replaceChildren();const top=items.slice(0,3),slots=top.length===1?[top[0]]:top.length===2?[top[1],top[0]]:[top[1],top[0],top[2]];slots.forEach((p,i)=>{const pos=top.length===1?1:top.length===2?(i===0?2:1):(i===1?1:i===0?2:3);const div=document.createElement('div');div.className='podium-player '+(pos===1?'first':pos===3?'third':'');const crown=document.createElement('span');crown.className='podium-crown';crown.textContent=pos===1?'✦':pos===2?'☆':'✿';const name=document.createElement('strong');name.className='podium-name';name.textContent=p?.name||'—';const score=document.createElement('span');score.className='podium-score';score.textContent=p?p.score+' pts':' ';const step=document.createElement('div');step.className='podium-step';step.textContent=pos;div.append(crown,name,score,step);els.podium.append(div);});}
function render(s){if(state?.session===s.session&&Number.isFinite(s.revision)&&Number.isFinite(state.revision)&&s.revision<state.revision)return;const previous=state?.status;state=s;skew=s.serverNow-Date.now();els.joined.textContent=s.players;els.lobbyConnected.textContent=s.connected;drawLobby(s.lobbyPlayers||[]);els.completeCount.textContent=s.completed+' / '+s.players;els.completeBar.style.width=(s.players?s.completed/s.players*100:0)+'%';els.liveJoined.textContent=s.players;els.liveConnected.textContent=s.connected;drawRank(s.leaderboard,els.liveRanks,7);drawRank(s.leaderboard,els.finalRanks,10);els.status.textContent=s.status==='paused'?'Ⅱ PAUSED':'● LIVE';els.status.style.background=s.status==='paused'?'#f7e0bb':'';els.paused= s.status==='paused';$('#pausedBanner').classList.toggle('hidden',s.status!=='paused');const desired=s.status==='waiting'?'lobby':['playing','paused'].includes(s.status)?'live':'results';if(s.status==='finished'){
 podium(s.leaderboard);els.finalSummary.textContent=`✿ ${s.players} players joined · ${s.completed} finished all 10 rounds`;
 }if(view!=='review'||s.status!=='finished'){if(desired!==view||previous!==s.status)safeView(desired);else safeView(view);}
}
function drawReview(){const q=reviewData?.questions[reviewIndex];if(!q)return;els.reviewNum.textContent=String(q.round).padStart(2,'0')+' / 10';els.reviewTheme.textContent=window.CareLabels.theme(q.theme);els.reviewQuestion.textContent=q.question;els.reviewOptions.replaceChildren();q.choices.forEach((choice,i)=>{const wrapper=document.createElement('div');wrapper.className='review-option'+(q.answer===i?' correct':'');const top=document.createElement('div');top.className='review-option-head';const label=document.createElement('span');label.textContent='ABCD'[i]+'. '+choice+(q.answer===i?' ✓':'');const n=document.createElement('span');n.textContent=q.counts[i]+' · '+(q.answered?Math.round(q.counts[i]/q.answered*100):0)+'%';top.append(label,n);const track=document.createElement('div');track.className='review-meter';const bar=document.createElement('span');bar.style.width=(q.answered?q.counts[i]/q.answered*100:0)+'%';track.append(bar);wrapper.append(top,track);els.reviewOptions.append(wrapper);});els.reviewExplain.textContent='✿ '+q.explain;els.reviewAnswered.textContent=q.answered;els.reviewCorrect.textContent=(q.answered?Math.round(q.correct/q.answered*100):0)+'%';els.reviewUnanswered.textContent=q.unanswered;els.prev.disabled=reviewIndex===0;els.next.disabled=reviewIndex===reviewData.questions.length-1;}
async function showReview(){if(!reviewData){try{reviewData=await hostFetch('review');}catch(e){message(e.message);return;}}safeView('review');drawReview();}
async function downloadExport(){try{const r=await fetch('/api/host/export',{headers:{'x-host-pin':pin},cache:'no-store'});if(!r.ok){const d=await r.json().catch(()=>({}));throw Error(d.error||'Eksport gagal');}const blob=await r.blob(),url=URL.createObjectURL(blob),link=document.createElement('a');link.href=url;link.download='care-tower-results.csv';link.click();setTimeout(()=>URL.revokeObjectURL(url),1000);message('Data jawapan berjaya dimuat turun.');}catch(e){message(e.message);}}
async function command(action){try{const result=await hostFetch(action,{method:'POST'});render(result);message(action==='reset'?'New game ready!':'Game status updated.');reviewData=null;}catch(e){message(e.message);}}
function buttonGuard(action,text){if(confirm(text))command(action);}
els.start.onclick=()=>command('start');els.pause.onclick=()=>command('pause');els.end.onclick=()=>buttonGuard('end','End the game now? Ranking akan dimuktamadkan.');els.reset.onclick=()=>buttonGuard('reset','Reset Care Tower? Semua pemain dan markah akan dikosongkan.');els.review.onclick=showReview;els.exportData.onclick=downloadExport;els.winners.onclick=()=>safeView('results');els.back.onclick=()=>safeView('results');els.prev.onclick=()=>{reviewIndex=Math.max(0,reviewIndex-1);drawReview();};els.next.onclick=()=>{reviewIndex=Math.min(9,reviewIndex+1);drawReview();};els.fullscreen.onclick=()=>{if(!document.fullscreenElement)document.documentElement.requestFullscreen?.().catch(()=>{});else document.exitFullscreen?.();};
function setUrl(url){if(!url)return;joinedUrl=url;els.joinUrl.textContent=new URL(url).host;els.qr.classList.remove('hidden');els.qrFallback.classList.add('hidden');els.qr.onload=()=>els.qrFallback.classList.add('hidden');els.qr.onerror=()=>{els.qr.classList.add('hidden');els.qrFallback.classList.remove('hidden');};els.qr.src='/api/qr.svg?url='+encodeURIComponent(url);}
async function links(){
 try{
  const d=await(await fetch('/api/links',{cache:'no-store'})).json();
  els.linkSelect.replaceChildren();
  const urls=(d.links||[]).filter(u=>/^https?:\/\//.test(u));
  const isLocal=['localhost','127.0.0.1'].includes(location.hostname);
  const defaultUrl=isLocal?(d.recommended||location.origin+'/'):location.origin+'/';
  for(const value of new Set([defaultUrl,...urls])){const opt=document.createElement('option');opt.value=value;opt.textContent=value;els.linkSelect.append(opt);}
  els.linkSelect.value=defaultUrl;els.linkSelect.classList.toggle('hidden',!isLocal);
  setUrl(defaultUrl);
 }catch{els.linkSelect.classList.add('hidden');setUrl(location.origin+'/');}
}
els.linkSelect.onchange=()=>setUrl(els.linkSelect.value);
function showBootCard(){els.auth.classList.remove('hidden');els.bootCard.classList.remove('hidden');els.authCard.classList.add('hidden');}
function showPinCard(){els.auth.classList.remove('hidden');els.bootCard.classList.add('hidden');els.authCard.classList.remove('hidden');}
async function unlock(){const value=els.pin.value.trim();if(!value){els.authError.textContent='Enter your presenter PIN.';return;}pin=value;try{await hostFetch('auth');sessionStorage.setItem('care-presenter-pin',pin);showBootCard();connect();}catch(e){pin='';els.authError.textContent=e.message;}}
els.pin.onkeydown=e=>{if(e.key==='Enter')unlock();};$('#unlock').onclick=unlock;
// Authenticate without changing state: /api/host/auth only checks PIN.
async function connect(){showBootCard();await links();try{const c=await(await fetch('/api/config',{cache:'no-store'})).json();window.CARE_CLOUD_MODE=!!c.cloud;render(await(await fetch('/api/state',{cache:'no-store'})).json());els.auth.classList.add('hidden');if(window.CARE_CLOUD_MODE){
  setInterval(async()=>{if(cloudPollBusy||document.hidden)return;cloudPollBusy=true;try{const r=await fetch('/api/state',{cache:'no-store'});if(!r.ok)throw Error('offline');render(await r.json());}catch{message('Connection lost · Sedang cuba sambung semula…');}finally{cloudPollBusy=false;}},2300);
 }else{
  events=new EventSource('/api/events');events.onmessage=e=>{try{render(JSON.parse(e.data));}catch{}};
  events.onerror=()=>message('Connection lost · Sedang cuba sambung semula…');
 }}catch{els.bootCard.querySelector('h2').textContent='Connection unavailable';els.bootCard.querySelector('p').textContent='Care Tower belum dapat dihubungi. Cuba refresh sebentar lagi.';message('Care Tower belum dapat dihubungi. Cuba refresh sebentar lagi.');}}
function tick(){if(!state)return;els.clock.textContent=fmt(state.status==='waiting'?240000:state.status==='paused'?state.remainingMs:Math.max(0,state.endsAt-(Date.now()+skew)));}
setInterval(tick,150);
(async()=>{pin=sessionStorage.getItem('care-presenter-pin')||'';if(pin){try{await hostFetch('auth');connect();return;}catch{sessionStorage.removeItem('care-presenter-pin');pin='';}}showPinCard();})();
})();
